                            possible.append((r, c))
                if not possible:
                    possible = [(r, c) for r in range(N) for c in range(N) if grid[r][c] == 0]
                return possible

        possible_cells = get_possible_cells()

        def is_valid(g: List[List[int]], r: int, c: int, n: int) -> bool:
            if n in g[r]:
                return False
            for row in range(len(g)):
                if g[row][c] == n:
                    return False
            sub_size = int(len(g) ** 0.5)
            sub_r = r // sub_size
            sub_c = c // sub_size
            for row in range(sub_r * sub_size, (sub_r + 1) * sub_size):
                for col in range(sub_c * sub_size, (sub_c + 1) * sub_size):
                    if g[row][col] == n:
                        return False
            return True

        def is_winning_move(r: int, c: int, n: int) -> bool:
            temp_grid = [row.copy() for row in grid]
            temp_grid[r][c] = n
            opponent_cells = []
            for x in range(N):
                for y in range(N):
                    if (x == r or y == c) and temp_grid[x][y] == 0:
                        opponent_cells.append((x, y))
            for (x, y) in opponent_cells:
                has_possible = False
                for m in range(1, N + 1):
                    if is_valid(temp_grid, x, y, m):
                        has_possible = True
                        break
                if has_possible:
                    return False
            return True

        winning_move = None
        for (r, c) in possible_cells:
            for n in range(1, N + 1):
                if is_valid(grid, r, c, n):
                    if is_winning_move(r, c, n):
                        winning_move = [(r, c), n]
                        break
            if winning_move:
