    grid = message.message[0].data[1]
    prev_move = message.message[0].data[0]
    n = len(grid)
    move = None

    # Helper function to compute possible cells based on prev_move
    possible_cells = []
    if prev_move is None:
        # First move: any empty cell
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 0:
                    possible_cells.append((i, j))
    else:
        # Get previous move's coordinates
        pr, pc = prev_move[0]
        # Check cells in row pr or column pc
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 0 and (i == pr or j == pc):
                    possible_cells.append((i, j))
        # If no cells found, any empty cell is allowed
        if not possible_cells:
            for i in range(n):
                for j in range(n):
                    if grid[i][j] == 0:
                        possible_cells.append((i, j))

    # Collect valid moves
    valid_moves = []
    root = int(n**0.5)
    for (i,j) in possible_cells:
        # Check possible values for (i,j)
        row = grid[i]
        col = [grid[x][j] for x in range(n)]
        bx = (i // root) * root
        by = (j // root) * root
        subgrid = []
        for x in range(bx, bx + root):
            for y in range(by, by + root):
                subgrid.append(grid[x][y])
        used = set(row + col + subgrid)
        possible_values = [v for v in range(1, n+1) if v not in used]
        for v in possible_values:
            valid_moves.append(((i,j), v))

    # Check for winning moves first
    winning_moves = []
    for move_candidate in valid_moves:
        (i,j), v = move_candidate
        # Simulate the move
        temp_grid = [row.copy() for row in grid]
        temp_grid[i][j] = v
        # Opponent must choose in row i or column j
        opponent_cells = []
        for x in range(n):
            for y in range(n):
                if temp_grid[x][y] == 0 and (x == i or y == j):
                    opponent_cells.append((x,y))
        # Check if all have no possible moves
        all_no = True
        for (x,y) in opponent_cells:
            # Check possible_ws for (x,y)
            row_x = temp_grid[x]
            col_y = [temp_grid[a][y] for a in range(n)]
            bx_sub = (x // root) * root
            by_sub = (y // root) * root
            subg = []
            for a in range(bx_sub, bx_sub + root):
                for b in range(by_sub, by_sub + root):
                    subg.append(temp_grid[a][b])
            used_ws = set(row_x + col_y + subg)
            possible_ws = [w for w in range(1, n+1) if w not in used_ws]
            if possible_ws:
                all_no = False
                break
        if all_no:
            winning_moves.append(move_candidate)

    if winning_moves:
        move = winning_moves[0]
    else:
        # Find the move that minimizes opponent's options
        best_move = None
        min_count = float('inf')
        for move_candidate in valid_moves:
            (i,j), v = move_candidate
            temp_grid = [row.copy() for row in grid]
            temp_grid[i][j] = v
            opponent_cells = []
            for x in range(n):
                for y in range(n):
                    if temp_grid[x][y] == 0 and (x == i or y == j):
                        opponent_cells.append((x,y))
            count = 0
            for (x,y) in opponent_cells:
                row_x = temp_grid[x]
                col_y = [temp_grid[a][y] for a in range(n)]
                bx_sub = (x // root) * root
                by_sub = (y // root) * root
                subg = []
                for a in range(bx_sub, bx_sub + root):
                    for b in range(by_sub, by_sub + root):
                        subg.append(temp_grid[a][b])
                used_ws = set(row_x + col_y + subg)
                possible_ws = [w for w in range(1, n+1) if w not in used_ws]
                if possible_ws:
                    count += 1
            if count < min_count:
                min_count = count
                best_move = move_candidate
            elif count == min_count and best_move is None:
                best_move = move_candidate
        move = best_move if best_move else valid_moves[0]

    return Info(
        sender=self.__class__.__name__,
        receiver=message.sender,
        difficulty=message.difficulty,
        message=[BaseMessageDataType(data=move, type='custom')]
    )

